from collections import deque
def comps(grid, val):
    R,C=len(grid),len(grid[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if grid[r][c]==val and not seen[r][c]:
                comp=[]; q=deque([(r,c)]); seen[r][c]=True
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<R and 0<=b<C and grid[a][b]==val and not seen[a][b]:
                            seen[a][b]=True; q.append((a,b))
                out.append(comp)
    return out
