def bb_exact_matches(grid, shape, val=0):
    R,C=len(grid),len(grid[0]); h=max(r for r,c in shape); w=max(c for r,c in shape)
    res=set()
    for r in range(R-h):
        for c in range(C-w):
            ok=True
            for dr in range(h+1):
                for dc in range(w+1):
                    v = grid[r+dr][c+dc]
                    if (dr,dc) in set(shape):
                        if v!=val: ok=False;break
                    else:
                        if v==val: ok=False;break
                if not ok: break
            if ok:
                for dr,dc in shape: res.add((r+dr,c+dc))
    return res
